class PriceEngine:
    def __init__(self):
        self.plans = {
            'basic': 1.0,
            'pro': 0.9  # 10% discount
        }

    def price(self, plan, amount):
        if plan not in self.plans:
            raise KeyError(f"Unknown plan: {plan}")

        discounted_price = amount * self.plans[plan]
        return round(discounted_price, 2)

    def discounts(self):
        return self.plans.copy()
